import{p as c,a as d}from"./gH3D-RDX.js";const a={getAdminCourses:async()=>{const s=await d("/admin/courses");if(!s.ok)throw new Error("Failed to fetch courses");return await s.json()},getAdminLessonsByCourseId:async s=>{const t=await d(`/admin/courses/${s}`);if(!t.ok)throw new Error("Failed to fetch lessons");return await t.json()},getStudentsByCourseId:async s=>{const t=await d(`/admin/courses/${s}/students`);if(!t.ok)throw new Error("Failed to fetch students");return t.json()},updateCourseOrder:async s=>{const t=await c("/admin/courses/order",s,"");if(!t.ok)throw new Error("Failed to update course order");return t.json()}};async function f(){const s=await a.getAdminCourses(),t=s.reduce((r,e)=>(r.add(e.type),r),new Set),o=Array.from(t);return{courses:s,course_types:o}}async function y(s){return await a.getAdminLessonsByCourseId(s)}async function p(s){const t=await a.getStudentsByCourseId(s),o=t.data,r=t.next_page_url,e=t.total,n=t.status_counts,u=t.item;return{students:o,item:u,nextPage:r,total:e,stats:n}}async function w(s){if(s.filter((e,n)=>e.order!==n).length===0)return;const o=s.map((e,n)=>({id:e.id,order:n}));return await a.updateCourseOrder(JSON.stringify(o))}export{y as a,f as b,p as f,w as u};
